with exploded as (select id, effective_from, currency, tier_value from price_tiers lateral view outer explode(discounts) e as tier_value), valid as (select *, case when currency = 'THB' then 1 else 0 end is_thb, date_format(effective_from, 'yyyy-MM-dd') effective_from_label from exploded where effective_from > date '2024-04-10'), metrics as (select *, avg(tier_value) over (partition by currency) currency_avg_tier_value from valid where tier_value < 23), with_windows as (select *, cume_dist() over (partition by date_trunc('MONTH', effective_from), currency order by currency_avg_tier_value desc nulls first) currency_avg_tier_value_cume_dist, rank() over (partition by date_trunc('week', effective_from), currency order by is_thb asc nulls first) is_thb_rank from metrics), enriched as (select *, rank() over (order by is_thb_rank desc) is_thb_rank_rank, cume_dist() over w_hist tier_value_cume_dist, min(tier_value) over w_running currency_min_tier_value from with_windows window w_hist as (partition by currency order by tier_value asc nulls last), w_running as (partition by currency)), scored as (select currency, tier_value, is_thb, is_thb_rank, is_thb_rank_rank, tier_value_cume_dist, sum(currency_min_tier_value) over w_part effective_from_month_sum_currency_min_tier_value from enriched window w_part as (partition by month(effective_from), currency)), scored_price_tiers as (select currency, is_thb_rank, is_thb_rank_rank, tier_value_cume_dist, effective_from_month_sum_currency_min_tier_value, sum(tier_value_cume_dist) over w_ordered currency_sum_tier_value_cume_dist, min(tier_value) over w_ordered currency_min_tier_value, percent_rank() over (order by tier_value desc) tier_value_percent_rank from scored window w_ordered as (partition by currency)), grouped as (select case when is_thb_rank_rank >= 8 then 'HIGH' else 'LOW' end as is_thb_rank_rank_tier, currency, sort_array(collect_set(currency)) as currency_list, sort_array(collect_set(currency)) as currency_list_2, size(collect_set(currency)) as num_currencies, round(sum(is_thb_rank_rank) / nullif(count(case when currency = 'EUR' then 1 end), 0), 2) as is_thb_rank_rank_per_eur from scored_price_tiers group by rollup (case when is_thb_rank_rank >= 8 then 'HIGH' else 'LOW' end, currency)) select is_thb_rank_rank_tier, currency, currency_list from grouped order by currency desc nulls last
